/* One on-site workflow for all four sources; no email credentials or mailto. */
(()=>{'use strict';
const $=s=>document.querySelector(s),copy=x=>JSON.parse(JSON.stringify(x)),sources={general:'Formulaire général',studio:'Studio 3D',cart:'Mon panier',bending:'Dossier de pliage'};
let draft=null,limits=null,busy=false,apiBase='',transport='',serviceEnabled=false,opener=null,urls=[],saving=Promise.resolve(),generation=0;
const dialog=document.createElement('dialog');dialog.id='mir-estimate-dialog';dialog.setAttribute('aria-labelledby','mir-estimate-title');dialog.innerHTML=`<header class="estimate-dialog-head"><div><p class="eyebrow">LES REVÊTEMENTS MIR</p><h2 id="mir-estimate-title">Demander une estimation</h2></div><button type="button" id="estimate-close" aria-label="Fermer la demande d’estimation">Fermer ×</button></header><p id="estimate-source"></p><p id="estimate-status" role="status" aria-live="polite"></p><form id="estimate-form"><fieldset id="estimate-fields"><legend>Vos coordonnées et votre chantier</legend><div class="estimate-fields"><label>Nom complet<input name="name" autocomplete="name" required maxlength="150"></label><label>Courriel<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label>Téléphone (facultatif)<input name="phone" type="tel" autocomplete="tel" maxlength="40"></label><label class="estimate-wide">Adresse du chantier<input name="street" autocomplete="street-address" required maxlength="250"></label><label>Ville<input name="city" autocomplete="address-level2" required maxlength="120"></label><label>Code postal<input name="postalCode" autocomplete="postal-code" required maxlength="20"></label></div><label class="estimate-honeypot" aria-hidden="true">Site web<input name="website" tabindex="-1" autocomplete="off"></label><label>Note pour l’équipe (facultatif)<textarea name="note" rows="3" maxlength="4000"></textarea></label><label>Ajouter des plans PDF (facultatifs)<input id="estimate-files" type="file" accept=".pdf,application/pdf" multiple></label><p id="estimate-limits"></p><ul id="estimate-file-list"></ul></fieldset><section class="estimate-review" aria-labelledby="estimate-review-title"><h3 id="estimate-review-title">Vérifiez votre demande</h3><div id="estimate-summary"></div><div id="estimate-pdf"></div></section><p id="estimate-draft-state" aria-live="polite"></p><p id="estimate-errors" role="alert"></p><p class="estimate-privacy">Vos plans et la version soumise du projet sont réservés à l’équipe MIR. La copie enregistrée ne suivra pas vos modifications ultérieures dans le Studio.</p><div class="estimate-submit"><button id="estimate-send" type="submit" class="mir-button" disabled>Envoyer ma demande</button><button id="estimate-new" type="button" hidden>Nouvelle demande</button></div></form>`;
(document.querySelector('[data-estimate-host]')||document.body).append(dialog);const form=$('#estimate-form'),fields=$('#estimate-fields'),send=$('#estimate-send'),status=$('#estimate-status'),errors=$('#estimate-errors');
function message(text){status.textContent=text;}
function human(n){return new Intl.NumberFormat('fr-CA',{maximumFractionDigits:1}).format(n/1048576)+' Mo';}
function save(){if(!draft)return Promise.resolve();const record=structuredClone({...draft,form:readForm(),updatedAt:Date.now()});draft.form=record.form;$('#estimate-draft-state').textContent='Enregistrement du brouillon…';saving=saving.catch(()=>{}).then(()=>window.MIREstimateDrafts.save(record)).then(()=>{$('#estimate-draft-state').textContent='Brouillon conservé sur cet appareil.';});return saving;}
function readForm(){const data=new FormData(form);return Object.fromEntries(['name','email','phone','street','city','postalCode','note'].map(k=>[k,String(data.get(k)??draft?.form?.[k]??'').trim()]));}
function restoreForm(values={}){for(const [key,value]of Object.entries(values)){const f=form.elements.namedItem(key);if(f&&'value'in f)f.value=value;}}
function clearURLs(){for(const u of urls)URL.revokeObjectURL(u);urls=[];}
function linkBlob(blob,label,filename,parent){const a=document.createElement('a'),url=URL.createObjectURL(blob);urls.push(url);a.href=url;a.download=filename;a.textContent=label;parent.append(a);}
function renderFiles(){const list=$('#estimate-file-list');list.replaceChildren();for(const [i,file]of (draft?.plans||[]).entries()){const li=document.createElement('li');linkBlob(file,file.name+' · '+human(file.size),file.name,li);if(!draft.submission&&!draft.received){const b=document.createElement('button');b.type='button';b.textContent='Retirer';b.setAttribute('aria-label','Retirer '+file.name);b.onclick=async()=>{draft.plans.splice(i,1);renderFiles();await save();};li.append(b);}list.append(li);}}
function appendGroup(parent,title,rows){const h=document.createElement('h4');h.textContent=title;const ul=document.createElement('ul');for(const row of rows){const li=document.createElement('li');li.textContent=typeof row==='string'?row:row.text||JSON.stringify(row);ul.append(li);}if(!rows.length){const li=document.createElement('li');li.textContent='À confirmer';ul.append(li);}parent.append(h,ul);}
function renderSummary(){const node=$('#estimate-summary');node.replaceChildren();const c=draft.context||{};if(draft.source==='studio'){const info=document.createElement('p');info.textContent='Métré préliminaire à valider. Les ouvertures sont conservées pour le métré.';node.append(info);appendGroup(node,'À estimer',c.studio?.estimate||[]);appendGroup(node,'Aperçu seulement',c.studio?.previewOnly||[]);}else if(c.rows?.length)appendGroup(node,'À estimer',c.rows);else{const p=document.createElement('p');p.textContent='Décrivez votre projet dans la note et ajoutez vos plans si vous en avez.';node.append(p);}if(c.issues){const p=document.createElement('p');p.className='estimate-warning';p.textContent=c.issues;node.append(p);}const pdf=$('#estimate-pdf');pdf.replaceChildren();if(c.dossier)linkBlob(c.dossier,'Vérifier le PDF du dossier',c.dossier.name,pdf);}
async function configuration(){const base=String(window.MIREstimateConfig?.apiBase||'').replace(/\/$/,'');limits=null;apiBase='';serviceEnabled=false;if(!base){message('Brouillon conservé sur cet appareil. L’envoi n’est pas encore raccordé.');$('#estimate-limits').textContent='Envoi non raccordé : les limites seront affichées dès que le service sera configuré. Vous pouvez conserver votre brouillon sur cet appareil.';return;}const u=new URL(base,location.href);const localTest=window.MIREstimateConfig?.environment==='test'&&['127.0.0.1','localhost'].includes(location.hostname)&&['127.0.0.1','localhost'].includes(u.hostname);if(u.protocol!=='https:'&&u.origin!==location.origin&&!localTest)throw Error('L’adresse du service d’estimation doit être sécurisée.');const r=await fetch(u.href+'/config',{credentials:'omit',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Le service d’estimation est indisponible. Votre brouillon reste conservé.');const c=await r.json();if(!c.limits||!Number.isFinite(c.limits.maxTotalFileBytes)||!Number.isFinite(c.limits.maxFileBytes)||!Number.isInteger(c.limits.maxFiles))throw Error('Les limites d’envoi n’ont pas pu être vérifiées.');limits=c.limits;apiBase=u.href;transport=c.transport||'multipart';if(c.enabled&&transport==='supabase-storage-v1')void window.MIREstimateUpload.prepareChallenge(apiBase).catch(()=>{});$('#estimate-limits').textContent=`Limites du service : ${limits.maxFiles} PDF au total, ${human(limits.maxFileBytes)} par fichier et ${human(limits.maxTotalFileBytes)} au total. Le PDF du dossier est compris dans ces limites.`;if(!c.enabled)message('L’envoi est temporairement indisponible : '+(c.message||'configuration du serveur à compléter')+'. Brouillon conservé sur cet appareil.');serviceEnabled=c.enabled===true;return serviceEnabled;}
async function validateFiles(plans,dossier){if(!limits)return 'Le service doit confirmer ses limites avant l’envoi.';const all=[...plans,...(dossier?[dossier]:[])];if(all.length>limits.maxFiles)return `Maximum ${limits.maxFiles} PDF par demande, dossier compris.`;let total=0;for(const f of all){total+=f.size;if(f.size>limits.maxFileBytes)return `${f.name} dépasse ${human(limits.maxFileBytes)}. Réduisez ce PDF ou retirez-le avant de réessayer.`;if(!/\.pdf$/i.test(f.name)||f.type&&!['application/pdf','application/octet-stream'].includes(f.type))return `${f.name} n’est pas un PDF accepté.`;if(await f.slice(0,5).text()!=='%PDF-')return `${f.name} ne contient pas un fichier PDF valide.`;}if(total>limits.maxTotalFileBytes)return `Les PDF dépassent ensemble ${human(limits.maxTotalFileBytes)}. Réduisez ou retirez des fichiers.`;return '';}
async function dossierFile(options){if(!window.MIRPDF?.makePlan)throw Error('Le moteur PDF n’est pas disponible. Rechargez cette page.');const result=await window.MIRPDF.makePlan(options);return new File([result.blob],result.filename,{type:'application/pdf',lastModified:0});}
async function context(source){if(source==='general')return {rows:[]};if(source==='studio'){if(!window.MIR_STUDY?.captureEstimation)throw Error('Attendez la fin du chargement du Studio avant de préparer votre demande.');const studio=await window.MIR_STUDY.captureEstimation(),project=await window.MIRProjectStore?.getActive();return {studio,rows:studio.estimate,plans:project?.sourceFile?[project.sourceFile]:[]};}if(source==='bending'){const order=window.MIRProductionWorkspace?.getEstimationDossier?.();if(!order?.items?.length)throw Error('Ajoutez une pièce à votre dossier avant de demander une estimation.');return {selection:{schema:'mir-bending-estimate-1',order},rows:pieceRows(order.items),dossier:await dossierFile({title:'MIR — Demande de pliage',subtitle:order.project||'Projet à confirmer',filename:'MIR-dossier-pliage.pdf',faces:window.MIRProduction.productionPages({...order,items:order.items.map(i=>i.snapshot||i.spec)},{document:'client-request'})})};}const api=window.MIRUnifiedClientDossier;if(!api)throw Error('Le dossier de votre panier n’a pas chargé.');const allowed=[...document.querySelectorAll('[data-selection-preview]')].map(e=>Number(e.dataset.selectionPreview)),state=api.read(localStorage,{allowedMaterialIndices:allowed});if(!state.ready)throw Error([...state.errors,state.legacyCount?'Reprenez vos anciens pliages dans le configurateur.':'',state.link!=='ready'?'Associez les noms de projet dans le dossier commun.':'','Vérifiez votre panier et les pièces avant l’envoi.'].filter(Boolean).join(' '));if(window.MIRCommerceValidateQuantity)for(const item of state.materials){const check=window.MIRCommerceValidateQuantity(item);if(!check.ok)throw Error(check.message);}return {selection:api.payload(state),rows:[...state.materials.map(x=>`${x.name||x.materialId} · Quantité ${x.quantity} ${x.unit||''} · Format ${x.formatName||'À confirmer'} · Teinte ${x.colorName||'À confirmer'}`),...pieceRows(state.pieces)],dossier:await dossierFile(api.pdfOptions(state,{selectionPDF:window.MIRSelectionPDF,production:window.MIRProduction}))};}
function pieceRows(items){return items.map(i=>{const s=i.spec||i;return `${s.name||i.id} · Quantité ${s.quantity} · ${s.material?.type||'Matériau à confirmer'} · Longueur ${s.length} ${s.unit||'in'} · Teinte ${[s.finish?.name,s.finish?.code].filter(Boolean).join(' / ')||'À confirmer'} · `+(s.segments?s.segments.map(x=>`${x.label} ${x.length}`).join(' / '):Object.entries(s.dimensions||{}).map(([k,v])=>k+' '+v).join(' / '));});}
async function knownContact(){
 const drafts=await Promise.all(Object.keys(sources).map(source=>window.MIREstimateDrafts.get(source).catch(()=>null))),latest=drafts.filter(x=>x?.form).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0))[0],values={};
 for(const key of ['name','email','phone'])if(latest?.form?.[key])values[key]=latest.form[key];
 try{const c=window.MIRPortalConfig;if(!c?.enabled||!window.MIRSupabase)return values;
  const sdk=window.MIRSupabase.createClient(c.supabaseUrl,c.publishableKey,{auth:{flowType:'pkce',detectSessionInUrl:false,storageKey:'mir_portal_auth_'+c.projectRef}}),session=await sdk.auth.getSession();if(!session.data?.session)return values;
  const identity=await sdk.auth.getUser();if(identity.error||!identity.data?.user)return values;const account=await sdk.rpc('mir_account_snapshot');if(account.error||account.data?.userId!==identity.data.user.id)return values;
  const a=account.data.addresses?.length===1?account.data.addresses[0]:null;
  return {...values,name:values.name||a?.recipient||identity.data.user.user_metadata?.full_name||'',email:values.email||identity.data.user.email||'',phone:values.phone||a?.phone||'',...(a?{street:[a.line1,a.line2].filter(Boolean).join(', '),city:a.city||'',postalCode:a.postalCode||''}:{})};
 }catch{return values;}
}
async function open(source='general'){if(busy)return;if(!sources[source])source='general';opener=document.activeElement;clearURLs();form.reset();draft=null;errors.textContent='';fields.disabled=false;send.disabled=true;$('#estimate-new').hidden=true;$('#estimate-source').textContent=sources[source];if(!dialog.open){if(document.body.dataset.estimatePage==='general')dialog.show();else dialog.showModal();}message('Préparation de votre demande…');const current=++generation;try{let previous=await window.MIREstimateDrafts.get(source);if(current!==generation)return;if(previous?.received){draft=previous;restoreForm(previous.form);renderFiles();renderSummary();fields.disabled=true;message('Demande reçue · '+previous.received.requestNumber);$('#estimate-new').hidden=false;return;}const ctx=previous?.submission?previous.context:await context(source);draft=previous||{source,requestId:crypto.randomUUID(),form:await knownContact(),plans:[],context:ctx};if(!previous?.submission){draft.context=ctx;if(source==='studio'&&ctx.plans?.length)draft.plans=ctx.plans;}restoreForm(draft.form);renderFiles();renderSummary();const enabled=await configuration();if(current!==generation)return;fields.disabled=!!draft.submission;if(draft.submission)message('Une tentative précédente attend confirmation. Réessayez la même demande pour éviter un doublon.');else if(enabled)message(previous?'Brouillon retrouvé sur cet appareil. Vérifiez votre demande.':'Votre demande est prête à vérifier. Aucun envoi effectué.');send.disabled=!enabled||!form.checkValidity();await save();}catch(e){errors.textContent=e.message;message('Aucune demande envoyée.');}}
form.addEventListener('input',()=>{if(serviceEnabled&&apiBase&&draft&&!draft.received&&!busy)send.disabled=!form.checkValidity();if(draft&&!draft.submission)void save().catch(e=>{errors.textContent=e.message;send.disabled=true;});});
$('#estimate-files').onchange=async e=>{if(!draft)return;const added=[...e.target.files];const proposed=[...draft.plans,...added];const issue=limits?await validateFiles(proposed,draft.context.dossier):'';if(issue){errors.textContent=issue;e.target.value='';return;}draft.plans=proposed;errors.textContent='';renderFiles();await save();e.target.value='';};
form.onsubmit=async e=>{e.preventDefault();if(busy||!draft||draft.received||!apiBase||!limits||!serviceEnabled)return;if(!draft.submission&&!form.reportValidity())return;errors.textContent='';busy=true;send.disabled=true;const issue=await validateFiles(draft.plans,draft.context.dossier);if(issue){errors.textContent=issue;busy=false;send.disabled=false;return;}fields.disabled=true;$('#estimate-close').disabled=true;try{if(!draft.submission){const f=draft.form;draft.submission={version:1,source:draft.source,contact:{name:f.name,email:f.email,phone:f.phone},address:{street:f.street,city:f.city,postalCode:f.postalCode},note:f.note,selection:draft.context.selection||null,studio:draft.context.studio||null};await save();}await saving;if(new Blob([JSON.stringify(draft.submission)]).size>limits.maxPayloadBytes)throw Error('Les vues du projet dépassent la taille acceptée par le service. Le brouillon reste conservé.');let result,response;if(transport==='supabase-storage-v1'){result=await window.MIREstimateUpload.send({base:apiBase,draft,save,progress:message,website:form.elements.namedItem('website').value});response={ok:true};}else{const body=new FormData();body.set('requestId',draft.requestId);body.set('payload',JSON.stringify(draft.submission));for(const file of draft.plans)body.append('plans',file,file.name);if(draft.context.dossier)body.append('dossier',draft.context.dossier,draft.context.dossier.name);message('Enregistrement et envoi de votre demande…');response=await fetch(apiBase,{method:'POST',body,credentials:'omit',signal:AbortSignal.timeout(120000)});try{result=await response.json();}catch{throw Error('La réponse du serveur a été interrompue. Réessayez cette même demande.');}}if(!response.ok||result.state!=='received'||!result.requestNumber){if([400,413,422].includes(response.status)&&result.retryable===false){draft.submission=null;fields.disabled=false;}throw Error(result.message||'La réception n’est pas confirmée. Votre brouillon est conservé ; réessayez.');}draft.received={requestNumber:result.requestNumber,id:result.id};await save().catch(()=>{errors.textContent='Votre demande est reçue. Notez son numéro : le navigateur n’a pas pu le conserver.';});message('Demande reçue · '+result.requestNumber+'. L’équipe MIR a été avisée.');$('#estimate-new').hidden=false;renderFiles();}catch(error){if(['PDF_INVALID','UPLOAD_REJECTED','IDEMPOTENCY_CONFLICT'].includes(error.result?.error))$('#estimate-new').hidden=false;errors.textContent=error.message||'La connexion a été interrompue. Réessayez la même demande.';message('Brouillon conservé. Aucune réception confirmée.');send.disabled=false;await save().catch(()=>{});}finally{busy=false;$('#estimate-close').disabled=false;}};
$('#estimate-close').onclick=()=>{if(!busy)dialog.close();};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});dialog.addEventListener('close',()=>{generation++;void save();opener?.focus();});$('#estimate-new').onclick=async()=>{const source=draft.source;await window.MIREstimateDrafts.remove(source);await open(source);};
document.addEventListener('click',e=>{const trigger=e.target.closest('[data-estimate-source],#cart-estimate');if(!trigger)return;e.preventDefault();e.stopImmediatePropagation();void open(trigger.dataset.estimateSource||'cart');},true);
window.MIREstimate=Object.freeze({open});if(document.body.dataset.estimatePage==='general')void open('general');if(new URLSearchParams(location.search).get('estimate')==='1')window.addEventListener('load',()=>{void open(document.body.dataset.commerceView==='selection'?'cart':'general');},{once:true});
})();
